import pandas as pd
import os

# List all experiment CSVs and their columns
for i in range(1, 8):
    fname = f"experiment_{i}_csv"
    path = eval(fname)
    df = pd.read_csv(path)
    print(f"Exp {i} columns: {list(df.columns)}")
    print(f"  Non-unit unique values:")
    for col in df.columns:
        if col != 'unit_id':
            if df[col].nunique() <= 10:
                print(f"    {col}: {sorted(df[col].unique())}")
            else:
                print(f"    {col}: range=[{df[col].min():.2f}, {df[col].max():.2f}], mean={df[df[col].notna()]['WaterClarityScore'].mean():.2f}")
